SELECT md.chembl_id AS molecule_chembl_id, md.pref_name AS molecule_name, md.max_phase, md.molecule_type, cs.canonical_smiles FROM molecule_dictionary md JOIN compound_records cr ON md.molregno = cr.molregno JOIN docs d ON cr.doc_id = d.doc_id AND d.chembl_id = 'CHEMBL1697781' LEFT JOIN compound_structures cs ON md.molregno = cs.molregno ORDER BY molecule_chembl_id;
